using System;using System.IO;using System.Collections.Generic;using Bokumyaku.Simulation;
public static class FirstWeekCandidateCheck{
public static object Run(){var rows=new List<object>();var milestones=new List<object>();foreach(int seed in new[]{42,73,101}){var meta=new MetaProgress();int elapsed=0,round=0,best=0,milestone=0,purchases=0,lastBuy=0;while(elapsed<756000){round++;var run=new RunSimulator(seed+round-1,meta);run.SetBuild(BuildPreset.Farming);run.SetWeapon(WeaponKind.Point);while(run.State==RunStatus.Running&&elapsed<756000){run.Tick();elapsed++;best=Math.Max(best,run.CompletedWave);if(elapsed==108000||elapsed==756000){var record=new RunSimulator(seed,meta);record.SetBuild(BuildPreset.Record);record.SetWeapon(WeaponKind.Point);for(int probe=0;probe<60000&&record.State==RunStatus.Running;probe++)record.Tick();if(record.State==RunStatus.Running)throw new Exception("Record probe did not end");milestones.Add(new{recordWave=record.CompletedWave,recordSeconds=record.TickCount/30.0,seed,hours=elapsed/108000.0,best,round,purchases,bank=meta.Crystals,levels=new[]{meta.Damage,meta.Supply,meta.Growth,meta.Harvest},incompleteRun=run.State==RunStatus.Running});}}if(run.State==RunStatus.Running)break;if(run.State!=RunStatus.Defeated)throw new Exception("Unexpected end");int reached=run.CompletedWave/5*5;int bonus=Math.Max(0,reached-milestone);milestone=Math.Max(milestone,reached);meta.Crystals+=run.CrystalsReward+bonus;int count=0,gap=0;for(int i=0;i<80;i++){MetaUpgrade chosen=MetaUpgrade.Damage;int level=int.MaxValue;foreach(MetaUpgrade k in Enum.GetValues(typeof(MetaUpgrade)))if(meta.Level(k)<MetaProgress.MaxLevel(k)&&meta.Level(k)<level){chosen=k;level=meta.Level(k);}if(level==int.MaxValue)break;int price=level<=20?Math.Max(500+25*level,meta.Cost(chosen)):meta.Cost(chosen);if(meta.Crystals<price)break;meta.Crystals-=price;switch(chosen){case MetaUpgrade.Damage:meta.Damage++;break;case MetaUpgrade.Supply:meta.Supply++;break;case MetaUpgrade.Growth:meta.Growth++;break;default:meta.Harvest++;break;}if(count==0)gap=round-lastBuy;lastBuy=round;count++;purchases++;}rows.Add(new{seed,round,seconds=run.TickCount/30.0,run.CompletedWave,normal=run.CrystalsReward,bonus,bank=meta.Crystals,bought=count,purchaseGap=gap,elapsedHours=elapsed/108000.0});}}
var report=new{candidate=500,policy="Point/Farming; seed increments each run; buy lowest-level research, tie Damage/Supply/Growth/Harvest, repeat until unaffordable. Hypothetical max(currentCost,500+25*level) up to20. No game/save changes. 1h/7h marks exclude unfinished rewards. Record probes use the milestone meta and base seed outside the time budget, so are diagnostic capacity, not achieved in-budget records.",milestones,rows};File.WriteAllText(Path.GetFullPath("../docs/evidence/first-week-candidate500.json"),Newtonsoft.Json.JsonConvert.SerializeObject(report,Newtonsoft.Json.Formatting.Indented));return milestones;}}
